SET NOCOUNT ON;
SET XACT_ABORT ON;

BEGIN TRY
    BEGIN TRANSACTION;

    IF OBJECT_ID(N'dbo.Sistema_Modulos', N'U') IS NULL
       OR OBJECT_ID(N'dbo.Sistema_ModulosMenus', N'U') IS NULL
       OR OBJECT_ID(N'dbo.Usuario_Modulos', N'U') IS NULL
       OR OBJECT_ID(N'dbo.Usuario_Acciones', N'U') IS NULL
       OR OBJECT_ID(N'dbo.Usuario_Roles', N'U') IS NULL
       OR OBJECT_ID(N'dbo.Usuario_PermisosRolModulo', N'U') IS NULL
    BEGIN
        THROW 51200, 'Faltan tablas canónicas de menú/RBAC para BOS Agentes e IA.', 1;
    END;

    DECLARE @SistemaModuloID INT;
    DECLARE @ModuloEsIdentity BIT = CONVERT(BIT, COLUMNPROPERTY(OBJECT_ID(N'dbo.Sistema_Modulos'), N'ModuloID', 'IsIdentity'));

    IF (SELECT COUNT(*) FROM dbo.Sistema_Modulos WHERE Codigo = N'BOS') > 1
        THROW 51201, 'Existen múltiples módulos Sistema_Modulos con Codigo BOS.', 1;

    SELECT TOP (1) @SistemaModuloID = ModuloID
    FROM dbo.Sistema_Modulos
    WHERE Codigo = N'BOS'
    ORDER BY ModuloID;

    IF @SistemaModuloID IS NULL
    BEGIN
        DECLARE @OrdenBOS INT;
        SELECT @OrdenBOS = ISNULL(MAX(Orden), 0) + 1 FROM dbo.Sistema_Modulos WITH (UPDLOCK, HOLDLOCK);

        IF @ModuloEsIdentity = 1
        BEGIN
            INSERT INTO dbo.Sistema_Modulos (Codigo, Nombre, Descripcion, Icono, Orden, EsPrincipal, EsSatelite, EsPortal, URLExterna, Activo, FechaCreacion)
            VALUES (N'BOS', N'BOS', N'Business Operating System EDARSAHUB', N'Bot', @OrdenBOS, 1, 0, 0, NULL, 1, GETDATE());
            SET @SistemaModuloID = CONVERT(INT, SCOPE_IDENTITY());
        END
        ELSE
        BEGIN
            SELECT @SistemaModuloID = ISNULL(MAX(ModuloID), 0) + 1 FROM dbo.Sistema_Modulos WITH (UPDLOCK, HOLDLOCK);
            INSERT INTO dbo.Sistema_Modulos (ModuloID, Codigo, Nombre, Descripcion, Icono, Orden, EsPrincipal, EsSatelite, EsPortal, URLExterna, Activo, FechaCreacion)
            VALUES (@SistemaModuloID, N'BOS', N'BOS', N'Business Operating System EDARSAHUB', N'Bot', @OrdenBOS, 1, 0, 0, NULL, 1, GETDATE());
        END;
    END
    ELSE
    BEGIN
        UPDATE dbo.Sistema_Modulos
        SET Activo = 1
        WHERE ModuloID = @SistemaModuloID;
    END;

    IF NOT EXISTS (SELECT 1 FROM dbo.Usuario_Modulos WHERE CodigoModulo = N'BOS_AGENTES')
    BEGIN
        INSERT INTO dbo.Usuario_Modulos (CodigoModulo, NombreModulo, Descripcion, Icono, Ruta, Activo)
        VALUES (N'BOS_AGENTES', N'Agentes e IA', N'Centro de agentes y capacidades de IA gobernadas por BOS', N'Bot', N'/bos/agentes-ia', 1);
    END
    ELSE
    BEGIN
        UPDATE dbo.Usuario_Modulos
        SET NombreModulo = N'Agentes e IA',
            Descripcion = N'Centro de agentes y capacidades de IA gobernadas por BOS',
            Icono = N'Bot',
            Ruta = N'/bos/agentes-ia',
            Activo = 1
        WHERE CodigoModulo = N'BOS_AGENTES';
    END;

    DECLARE @UsuarioModuloID INT;
    DECLARE @AccionVerID INT;
    SELECT @UsuarioModuloID = ModuloID FROM dbo.Usuario_Modulos WHERE CodigoModulo = N'BOS_AGENTES' AND Activo = 1;
    SELECT TOP (1) @AccionVerID = AccionID FROM dbo.Usuario_Acciones WHERE CodigoAccion = N'VER' AND Activo = 1 ORDER BY AccionID;

    IF @UsuarioModuloID IS NULL THROW 51202, 'No fue posible resolver BOS_AGENTES en Usuario_Modulos.', 1;
    IF @AccionVerID IS NULL THROW 51203, 'No existe la acción VER activa.', 1;

    DECLARE @RolesObjetivo TABLE (CodigoRol VARCHAR(100) NOT NULL PRIMARY KEY);
    INSERT INTO @RolesObjetivo (CodigoRol) VALUES ('SUPERADMIN'), ('SUPERADMINISTRADOR'), ('ADMIN'), ('ADMINISTRADOR');

    UPDATE prm
    SET prm.Permitido = 1, prm.Activo = 1
    FROM dbo.Usuario_PermisosRolModulo prm
    INNER JOIN dbo.Usuario_Roles r ON r.RolID = prm.RolID
    INNER JOIN @RolesObjetivo o ON o.CodigoRol = r.CodigoRol
    WHERE prm.ModuloID = @UsuarioModuloID AND prm.AccionID = @AccionVerID AND r.Activo = 1;

    INSERT INTO dbo.Usuario_PermisosRolModulo (RolID, ModuloID, AccionID, Permitido, RestriccionPropietario, RestriccionSucursal, RequiereAutorizacion, Activo, FechaAlta, CreatedBy)
    SELECT r.RolID, @UsuarioModuloID, @AccionVerID, 1, 0, 0, 0, 1, SYSDATETIME(), N'BOS_AGENTES_GATE6B'
    FROM dbo.Usuario_Roles r
    INNER JOIN @RolesObjetivo o ON o.CodigoRol = r.CodigoRol
    WHERE r.Activo = 1
      AND NOT EXISTS (
          SELECT 1 FROM dbo.Usuario_PermisosRolModulo prm
          WHERE prm.RolID = r.RolID AND prm.ModuloID = @UsuarioModuloID AND prm.AccionID = @AccionVerID
      );

    DECLARE @MenuEsIdentity BIT = CONVERT(BIT, COLUMNPROPERTY(OBJECT_ID(N'dbo.Sistema_ModulosMenus'), N'MenuID', 'IsIdentity'));
    DECLARE @MenuPadreID INT;
    DECLARE @MenuCentroID INT;

    IF (SELECT COUNT(*) FROM dbo.Sistema_ModulosMenus WHERE Codigo = N'bos.agentes_ia' OR Ruta = N'/bos/agentes-ia') > 1
        THROW 51204, 'Existen múltiples registros para bos.agentes_ia.', 1;

    SELECT TOP (1) @MenuPadreID = MenuID
    FROM dbo.Sistema_ModulosMenus
    WHERE Codigo = N'bos.agentes_ia' OR Ruta = N'/bos/agentes-ia'
    ORDER BY MenuID;

    IF @MenuPadreID IS NULL
    BEGIN
        IF @MenuEsIdentity = 1
        BEGIN
            INSERT INTO dbo.Sistema_ModulosMenus (ModuloID, MenuPadreID, Codigo, Nombre, Descripcion, Icono, Ruta, Orden, RequierePermiso, Activo, FechaCreacion)
            SELECT @SistemaModuloID, NULL, N'bos.agentes_ia', N'Agentes e IA', N'Gobierno y operación de agentes BOS', N'Bot', N'/bos/agentes-ia', ISNULL(MAX(Orden), 0) + 1, N'BOS_AGENTES', 1, GETDATE()
            FROM dbo.Sistema_ModulosMenus WHERE ModuloID = @SistemaModuloID;
            SET @MenuPadreID = CONVERT(INT, SCOPE_IDENTITY());
        END
        ELSE
        BEGIN
            SELECT @MenuPadreID = ISNULL(MAX(MenuID), 0) + 1 FROM dbo.Sistema_ModulosMenus WITH (UPDLOCK, HOLDLOCK);
            INSERT INTO dbo.Sistema_ModulosMenus (MenuID, ModuloID, MenuPadreID, Codigo, Nombre, Descripcion, Icono, Ruta, Orden, RequierePermiso, Activo, FechaCreacion)
            SELECT @MenuPadreID, @SistemaModuloID, NULL, N'bos.agentes_ia', N'Agentes e IA', N'Gobierno y operación de agentes BOS', N'Bot', N'/bos/agentes-ia', ISNULL(MAX(Orden), 0) + 1, N'BOS_AGENTES', 1, GETDATE()
            FROM dbo.Sistema_ModulosMenus WHERE ModuloID = @SistemaModuloID;
        END;
    END
    ELSE
    BEGIN
        UPDATE dbo.Sistema_ModulosMenus
        SET ModuloID = @SistemaModuloID, MenuPadreID = NULL, Codigo = N'bos.agentes_ia', Nombre = N'Agentes e IA', Descripcion = N'Gobierno y operación de agentes BOS', Icono = N'Bot', Ruta = N'/bos/agentes-ia', RequierePermiso = N'BOS_AGENTES', Activo = 1
        WHERE MenuID = @MenuPadreID;
    END;

    IF (SELECT COUNT(*) FROM dbo.Sistema_ModulosMenus WHERE Codigo = N'bos.centro_agentes' OR Ruta = N'/bos/agentes-ia/centro-agentes') > 1
        THROW 51205, 'Existen múltiples registros para bos.centro_agentes.', 1;

    SELECT TOP (1) @MenuCentroID = MenuID
    FROM dbo.Sistema_ModulosMenus
    WHERE Codigo = N'bos.centro_agentes' OR Ruta = N'/bos/agentes-ia/centro-agentes'
    ORDER BY MenuID;

    IF @MenuCentroID IS NULL
    BEGIN
        IF @MenuEsIdentity = 1
        BEGIN
            INSERT INTO dbo.Sistema_ModulosMenus (ModuloID, MenuPadreID, Codigo, Nombre, Descripcion, Icono, Ruta, Orden, RequierePermiso, Activo, FechaCreacion)
            VALUES (@SistemaModuloID, @MenuPadreID, N'bos.centro_agentes', N'Centro de Agentes', N'Catálogo y estado de agentes BOS', N'Bot', N'/bos/agentes-ia/centro-agentes', 10, N'BOS_AGENTES', 1, GETDATE());
            SET @MenuCentroID = CONVERT(INT, SCOPE_IDENTITY());
        END
        ELSE
        BEGIN
            SELECT @MenuCentroID = ISNULL(MAX(MenuID), 0) + 1 FROM dbo.Sistema_ModulosMenus WITH (UPDLOCK, HOLDLOCK);
            INSERT INTO dbo.Sistema_ModulosMenus (MenuID, ModuloID, MenuPadreID, Codigo, Nombre, Descripcion, Icono, Ruta, Orden, RequierePermiso, Activo, FechaCreacion)
            VALUES (@MenuCentroID, @SistemaModuloID, @MenuPadreID, N'bos.centro_agentes', N'Centro de Agentes', N'Catálogo y estado de agentes BOS', N'Bot', N'/bos/agentes-ia/centro-agentes', 10, N'BOS_AGENTES', 1, GETDATE());
        END;
    END
    ELSE
    BEGIN
        UPDATE dbo.Sistema_ModulosMenus
        SET ModuloID = @SistemaModuloID, MenuPadreID = @MenuPadreID, Codigo = N'bos.centro_agentes', Nombre = N'Centro de Agentes', Descripcion = N'Catálogo y estado de agentes BOS', Icono = N'Bot', Ruta = N'/bos/agentes-ia/centro-agentes', Orden = 10, RequierePermiso = N'BOS_AGENTES', Activo = 1
        WHERE MenuID = @MenuCentroID;
    END;

    COMMIT TRANSACTION;

    SELECT N'BOS_AGENTES_IA_MIGRATION_READY' AS resultado, @SistemaModuloID AS sistema_modulo_id, @UsuarioModuloID AS usuario_modulo_id, @MenuPadreID AS menu_padre_id, @MenuCentroID AS menu_centro_id;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    THROW;
END CATCH;

