import React from 'react';
import { Link } from 'react-router-dom';
import { Bot, ShieldCheck, Gauge, Network } from 'lucide-react';
import { Card, CardContent } from '@/components/ui/card';

const items = [
  { icon: Bot, title: 'Centro de Agentes', text: 'Catálogo y estado de agentes autorizados por BOS.', to: '/bos/agentes-ia/centro-agentes' },
  { icon: ShieldCheck, title: 'Gobierno', text: 'RBAC, scopes, riesgo y clasificación de datos antes de cualquier ejecución.' },
  { icon: Gauge, title: 'Budgets', text: 'Límites explícitos por capacidad: llamadas externas, tiempo y demás presupuestos.' },
  { icon: Network, title: 'Execution Gate', text: 'Las capacidades se resuelven por Agent Harness y pasan por gates canónicos.' },
];

export default function AgentesIAHub() {
  return (
    <div className="space-y-6">
      <div>
        <p className="text-sm font-medium text-zinc-500">BOS</p>
        <h1 className="text-2xl font-bold text-zinc-900">Agentes e IA</h1>
        <p className="text-zinc-500 mt-1">Control de agentes, capacidades y ejecución gobernada. Ningún módulo obtiene privilegios por usar IA.</p>
      </div>
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-4">
        {items.map(({ icon: Icon, title, text, to }) => {
          const body = (
            <Card className="h-full">
              <CardContent className="pt-6">
                <Icon className="h-7 w-7 mb-4" />
                <h2 className="font-semibold text-zinc-900">{title}</h2>
                <p className="text-sm text-zinc-500 mt-2">{text}</p>
                {to && <p className="text-sm font-medium mt-4">Abrir →</p>}
              </CardContent>
            </Card>
          );
          return to ? <Link key={title} to={to}>{body}</Link> : <div key={title}>{body}</div>;
        })}
      </div>
    </div>
  );
}

